package org.humanjourney.core.npc.economy;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import org.humanjourney.core.npc.context.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
class EconomyTest {
 final Map<String,Set<String>> vocabulary=GeoProfile.vocabulary(null);
 Path root(){return Path.of(System.getProperty("humanjourney.projectDir"),"example-economy-datapack/data/human_journey");}
 JsonObject json(String path)throws Exception{return JsonParser.parseString(Files.readString(root().resolve(path))).getAsJsonObject();}
 GeoProfile profile()throws Exception{return GeoProfile.parse(json("npc_geography/synthetic.json").getAsJsonArray("macro_regions").get(0).getAsJsonObject().get("profile"),vocabulary);}
 GeoProfile.Availability any(){var o=new JsonObject();GeoProfile.DIMENSIONS.forEach(d->o.addProperty(d,"any"));return GeoProfile.availability(o,vocabulary);}
 NpcContext context(){return new NpcContext("era_test","none","test_macro","test_local","none");}
 EconomyCatalog.Items items=(id,components)->id.equals("minecraft:wooden_shovel")?1:id.startsWith("minecraft:")?64:0;
 List<NpcContextStore.Source> files(String prefix)throws Exception{var out=new ArrayList<NpcContextStore.Source>();try(var paths=Files.list(root().resolve(prefix))){for(var p:paths.sorted().toList())out.add(new NpcContextStore.Source("human_journey:"+p.getFileName().toString().replace(".json",""),"synthetic",Files.readString(p)));}return out;}
 NpcContextStore.Data data()throws Exception{return NpcContextStore.prepare(new NpcContextStore.Source("human_journey:core/npc_context","test",json("core/npc_context.json").toString()),files("npc_geography"),files("npc_archetype"),id->items.maximum(id,new JsonObject()),files("npc_commodity").stream().map(s->new EconomyCatalog.Source(s.id(),s.json())).toList(),files("npc_family").stream().map(s->new EconomyCatalog.Source(s.id(),s.json())).toList(),null,items);}
 @AfterEach void clear(){NpcContextStore.reset();}
 @Test void localCompleteProfileReplacesMacroAndMacroIsFallback()throws Exception{var d=data();assertEquals(Set.of("wet"),d.geography().profile("test_macro","test_local").values().get("moisture"));assertEquals(Set.of("dry"),d.geography().profile("test_macro","none").values().get("moisture"));assertTrue(d.geography().profile("none","none").values().values().stream().allMatch(Set::isEmpty));}
 @Test void anyMultiValueAndAndIntersectionRules()throws Exception{var p=profile();assertTrue(any().matches(p));var o=new JsonObject();GeoProfile.DIMENSIONS.forEach(d->o.addProperty(d,"any"));o.add("water",JsonParser.parseString("[\"river\",\"lake\"]"));assertTrue(GeoProfile.availability(o,vocabulary).matches(p));o.add("temperature",JsonParser.parseString("[\"hot\"]"));assertFalse(GeoProfile.availability(o,vocabulary).matches(p));assertFalse(GeoProfile.availability(o,vocabulary).explain(p).get("temperature"));assertTrue(GeoProfile.availability(o,vocabulary).explain(p).get("water"));}
 @Test void specialUsesSameIntersectionAndEmptyProfileDoesNotPassRestrictedCommodity()throws Exception{var j=json("npc_geography/synthetic.json").getAsJsonArray("macro_regions").get(0).getAsJsonObject().getAsJsonObject("profile");j.add("special",JsonParser.parseString("[\"cave_access\",\"mountain_access\"]"));var p=GeoProfile.parse(j,vocabulary);var o=new JsonObject();GeoProfile.DIMENSIONS.forEach(d->o.addProperty(d,"any"));o.add("special",JsonParser.parseString("[\"mountain_access\"]"));var a=GeoProfile.availability(o,vocabulary);assertTrue(a.matches(p));assertFalse(a.matches(GeoProfile.none()));}
 @Test void vocabularyMissingDimensionsUnknownValuesAndMalformedAvailabilityReject()throws Exception{var p=json("npc_geography/synthetic.json").getAsJsonArray("macro_regions").get(0).getAsJsonObject().getAsJsonObject("profile");p.remove("water");assertThrows(IllegalArgumentException.class,()->GeoProfile.parse(p,vocabulary));var o=new JsonObject();GeoProfile.DIMENSIONS.forEach(d->o.addProperty(d,"any"));o.add("water",JsonParser.parseString("[\"unregistered\"]"));assertThrows(IllegalArgumentException.class,()->GeoProfile.availability(o,vocabulary));o.add("water",new JsonArray());assertThrows(IllegalArgumentException.class,()->GeoProfile.availability(o,vocabulary));}
 @Test void vocabularyCanBeExtendedThroughData(){var v=GeoProfile.vocabulary(JsonParser.parseString("{\"schema_version\":1,\"additions\":{\"special\":[\"test_access\"]}}"));assertTrue(v.get("special").contains("test_access"));assertFalse(vocabulary.get("special").contains("test_access"));}
 BarterSolver.Good good(String id,long value,int stack){return new BarterSolver.Good(id,value,stack);}
 @Test void exactOneSlotMayChangeOutputQuantity(){var r=BarterSolver.solve(good("B",5,64),List.of(good("A",2,64))).orElseThrow();assertEquals(1,r.priority());assertEquals(5,r.first().count());assertEquals(2,r.outputCount());assertEquals(0,r.error());}
 @Test void exactTwoSlotsMayUseSameNonStackableTwice(){var r=BarterSolver.solve(good("out",16,1),List.of(good("tool",8,1))).orElseThrow();assertEquals(2,r.priority());assertEquals(1,r.first().count());assertEquals(1,r.second().count());}
 @Test void threeNonStackableToolsCannotFitTwoSlots(){assertTrue(BarterSolver.solve(good("out",24,1),List.of(good("tool",8,1))).isEmpty());}
 @Test void quantitiesAboveStackSizeSplitAcrossSlots(){var r=BarterSolver.solve(good("out",100,1),List.of(good("input",1,64))).orElseThrow();assertEquals(2,r.priority());assertEquals(64,r.first().count());assertEquals(36,r.second().count());}
 @Test void approximateOneInputPrecedesApproximateTwo(){var r=BarterSolver.solve(good("out",10,1),List.of(good("A",9,1))).orElseThrow();assertEquals(3,r.priority());assertEquals(1,r.error());}
 @Test void approximateTwoAndRejectGreaterThanTenPercent(){var r=BarterSolver.solve(good("out",11,1),List.of(good("A",5,1))).orElseThrow();assertEquals(4,r.priority());assertEquals(1,r.error());assertTrue(BarterSolver.solve(good("out",10,1),List.of(good("A",3,1))).isEmpty());}
 @Test void exactTwoBeatsApproximateOneAndExactOneHasTopPriority(){var r=BarterSolver.solve(good("out",10,1),List.of(good("near",9,1),good("half",5,1))).orElseThrow();assertEquals(2,r.priority());assertEquals(0,r.error());}
 @Test void npcFavourableTieAndFewestTotalItemsAreDeterministic(){var r=BarterSolver.solve(good("out",10,1),List.of(good("low",9,1),good("high",11,1))).orElseThrow();assertEquals("high",r.first().good().id());assertEquals(r,BarterSolver.solve(good("out",10,1),List.of(good("high",11,1),good("low",9,1))).orElseThrow());}
 @Test void outputQuantityNeverExceedsActualLimitAndSelfPaymentIsExcluded(){var r=BarterSolver.solve(good("out",5,1),List.of(good("in",2,64)));assertTrue(r.isEmpty());assertTrue(BarterSolver.solve(good("same",5,64),List.of(good("same",5,64))).isEmpty());}
 @Test void familiesResolveDefaultExplicitAndContextMembers()throws Exception{var d=data();var f=d.economy().families().get("human_journey:test_log");assertEquals("minecraft:birch_log",f.resolve(context(),null));assertEquals("minecraft:spruce_log",f.resolve(context(),"minecraft:spruce_log"));assertEquals("minecraft:oak_log",f.resolve(new NpcContext("era_test","none","none","none","none"),null));assertThrows(IllegalArgumentException.class,()->f.resolve(context(),"minecraft:stone"));}
 @Test void everyMatchingSellerProducesOfferAndBuyingIgnoresGeography()throws Exception{var d=data();var settings=d.archetypes().get("human_journey:test_trader").economy(context());var plan=EconomyGenerator.generate(d.economy(),"human_journey:test_trader",context(),d.geography().profile("test_macro","test_local"),settings,items);assertEquals(1,plan.matchingSellers());assertEquals(1,plan.offers().size());assertEquals(5,plan.offers().getFirst().barter().first().count());assertFalse(d.economy().commodities().get("human_journey:test_payment").availability().matches(profile()));var empty=EconomyGenerator.generate(d.economy(),"human_journey:test_trader",context(),GeoProfile.none(),settings,items);assertEquals(0,empty.offers().size());assertEquals(0,empty.matchingSellers());}
 @Test void noRandomCatalogReductionAndRarityDoesNotControlAppearance()throws Exception{var d=data();var goods=new TreeMap<>(d.economy().commodities());var out=goods.get("human_journey:test_output");for(int i=0;i<80;i++)goods.put("test:out"+i,new EconomyCatalog.Commodity("test:out"+i,out.era(),out.value(),"rare_test_"+i,3,out.sellers(),out.buyers(),out.item(),null,any(),new JsonObject()));var catalog=new EconomyCatalog(goods,d.economy().families());var plan=EconomyGenerator.generate(catalog,"human_journey:test_trader",context(),profile(),d.archetypes().get("human_journey:test_trader").economy(context()),items);assertEquals(81,plan.matchingSellers());assertEquals(81,plan.offers().size());}
 @Test void unsolvableSellerIsSkippedAndReported()throws Exception{var d=data();var out=d.economy().commodities().get("human_journey:test_output");var catalog=new EconomyCatalog(Map.of(out.id(),out),d.economy().families());var plan=EconomyGenerator.generate(catalog,"human_journey:test_trader",context(),profile(),EconomySettings.parse(JsonParser.parseString("{\"enabled\":true}")),items);assertEquals(1,plan.matchingSellers());assertEquals(0,plan.offers().size());assertTrue(plan.skipped().get(out.id()).contains("no legal payment"));}
 @Test void commodityValidationRejectsBadValuesRolesErasItemsMaxUsesAndSelectors()throws Exception{var d=data();for(String field:List.of("value","maxUses","era","sellers","item")){var c=json("npc_commodity/test_output.json");switch(field){case "value"->c.addProperty(field,0);case "maxUses"->c.addProperty(field,-1);case "era"->c.addProperty(field,"missing");case "sellers"->c.add(field,JsonParser.parseString("[\"unknown_role\"]"));case "item"->c.addProperty(field,"missing:item");}assertThrows(IllegalArgumentException.class,()->EconomyCatalog.parse(List.of(new EconomyCatalog.Source("test:bad",c.toString())),List.of(),d.eraRules().ids(),d.archetypes(),d.geography(),vocabulary,items));}var c=json("npc_commodity/test_output.json");c.addProperty("family","test_log");assertThrows(IllegalArgumentException.class,()->EconomyCatalog.parse(List.of(new EconomyCatalog.Source("test:bad",c.toString())),List.of(),d.eraRules().ids(),d.archetypes(),d.geography(),vocabulary,items));}
 @Test void invalidEmptyAndUnknownFamilyMembersReject()throws Exception{var d=data();for(String members:List.of("[]","[\"missing:item\"]")){var f=json("npc_family/test_log.json");f.add("members",JsonParser.parseString(members));assertThrows(IllegalArgumentException.class,()->EconomyCatalog.parse(List.of(),List.of(new EconomyCatalog.Source("test:bad",f.toString())),d.eraRules().ids(),d.archetypes(),d.geography(),vocabulary,items));}}
 @Test void lastValidAtomicContextCatalogRemainsAfterRejectedReload()throws Exception{var d=data();NpcContextStore.accept(d);var state=NpcContextStore.state();NpcContextStore.reject("bad commodity");assertSame(d,NpcContextStore.state().data());assertEquals(state.revision(),NpcContextStore.state().revision());assertEquals(state.lastSuccess(),NpcContextStore.state().lastSuccess());}
 @Test void hundredsOfAreasAndPatchesValidateAndResolve()throws Exception{var geo=json("npc_geography/synthetic.json");var locals=new JsonArray();var patches=new JsonObject();for(int i=0;i<600;i++){var local=new JsonObject();local.addProperty("id","area_"+i);local.addProperty("macro_region","test_macro");local.add("profile",json("npc_geography/synthetic.json").getAsJsonArray("macro_regions").get(0).getAsJsonObject().get("profile"));int x=i*4;local.add("polygon",JsonParser.parseString("[["+x+",0],["+(x+2)+",0],["+(x+2)+",2],["+x+",2]]"));locals.add(local);patches.add("area_"+i,new JsonObject());}geo.add("local_areas",locals);var role=json("npc_archetype/test_trader.json");role.getAsJsonObject("eras").getAsJsonObject("era_test").add("local_areas",patches);long started=System.nanoTime();var d=NpcContextStore.prepare(new NpcContextStore.Source("test:context","test",json("core/npc_context.json").toString()),List.of(new NpcContextStore.Source("test:geo","test",geo.toString())),List.of(new NpcContextStore.Source("human_journey:test_trader","test",role.toString())),id->64);assertEquals(600,d.geography().locals().size());assertTrue(d.validatedVariants()>3000);assertEquals("area_599",d.geography().resolve("minecraft:overworld",599*4+1,1,"era_test").local());assertTrue(System.nanoTime()-started<30_000_000_000L,"synthetic reload unexpectedly slow");}
 @Test void hundredsOfGeographyResourcesHaveNoOld64FileLimit()throws Exception{var sources=new ArrayList<NpcContextStore.Source>();var original=json("npc_geography/synthetic.json");sources.add(new NpcContextStore.Source("test:macro","test","{\"schema_version\":1,\"macro_regions\":"+original.getAsJsonArray("macro_regions")+"}"));for(int i=0;i<520;i++){var local=original.getAsJsonArray("local_areas").get(0).getAsJsonObject().deepCopy();local.addProperty("id","part_"+i);local.addProperty("priority",i);sources.add(new NpcContextStore.Source("test:part_"+i,"test","{\"schema_version\":1,\"local_areas\":["+local+"]}"));}var d=NpcContextStore.prepare(new NpcContextStore.Source("test:context","test",json("core/npc_context.json").toString()),sources,files("npc_archetype"),id->64);assertEquals(520,d.geography().locals().size());assertEquals("part_519",d.geography().resolve("minecraft:overworld",20,20,"era_test").local());}
 @Test void noMacroSpecialTagsLeakIntoCompleteLocalProfile()throws Exception{var j=json("npc_geography/synthetic.json");j.getAsJsonArray("macro_regions").get(0).getAsJsonObject().getAsJsonObject("profile").add("special",JsonParser.parseString("[\"cave_access\"]"));var geo=NpcGeography.parse(List.of(j),Set.of("era_test"));assertEquals(Set.of("cave_access"),geo.profile("test_macro","none").values().get("special"));assertTrue(geo.profile("test_macro","test_local").values().get("special").isEmpty());}
 @Test void overlappingFamilyRulesRejectEvenWhenNotCurrentlyUsed()throws Exception{var d=data();var f=json("npc_family/test_log.json");var rules=f.getAsJsonArray("output_overrides");rules.add(rules.get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->EconomyCatalog.parse(List.of(),List.of(new EconomyCatalog.Source("test:duplicate_rules",f.toString())),d.eraRules().ids(),d.archetypes(),d.geography(),vocabulary,items));}
 @Test void boundedMovementMathAndDefaultSettings(){var s=EconomySettings.parse(JsonParser.parseString("{\"enabled\":true}"));assertTrue(s.wandering());assertTrue(s.lookAtPlayers());assertEquals(10,s.wanderRadius());assertTrue(EconomyMovement.inside(.5,64,.5,5,64,5,10));assertFalse(EconomyMovement.inside(.5,64,.5,11,64,11,10));assertFalse(EconomySettings.off().enabled());}
 ClassNode read(String name)throws Exception{try(var in=getClass().getClassLoader().getResourceAsStream(name+".class")){assertNotNull(in);var c=new ClassNode();new ClassReader(in).accept(c,0);return c;}}
 @Test void managedMovementEnablesAiRecordsHomeAndDoesNotChangeStaticTemplateParser()throws Exception{var c=read("org/humanjourney/core/npc/economy/EconomyMovement");var calls=new HashSet<String>();for(var m:c.methods)for(var i:m.instructions)if(i instanceof MethodInsnNode call)calls.add(call.name);assertTrue(calls.containsAll(Set.of("setNoAi","setHomeTo","getEntityGoalSelector","removeAllGoals")));var d=data();var staticJson=JsonParser.parseString(Files.readString(Path.of(System.getProperty("humanjourney.projectDir"),"example-npc-datapack/data/human_journey/npc/story_test.json")));assertTrue(org.humanjourney.core.npc.NpcTemplate.parse("human_journey:story_test",staticJson).stationary());}
 @Test void nativeCostAndSanitizerCompatibilityHooksAreScoped()throws Exception{var c=read("org/humanjourney/core/npc/economy/mixin/ItemCostMixin");assertTrue(c.methods.stream().anyMatch(m->m.name.equals("hjPayment")));var nativeCost=read("net/minecraft/world/item/trading/ItemCost");assertTrue(nativeCost.methods.stream().anyMatch(m->m.name.equals("test")&&m.desc.equals("(Lnet/minecraft/world/item/ItemStack;)Z")));var nativeNpc=read("de/markusbordihn/easynpc/entity/easynpc/data/TradingDataCapable");var sanitizer=nativeNpc.methods.stream().filter(m->m.name.equals("sanitizeTradingOffers")).findFirst().orElseThrow();int calls=0;for(var i:sanitizer.instructions)if(i instanceof MethodInsnNode call&&call.name.equals("getItemCost"))calls++;assertEquals(2,calls);}
}
